namespace PromptOptimizer.Application.DTOs;

/// <summary>
/// Actual token usage reported by the LLM provider for a single optimization call.
/// </summary>
public class TokenUsage
{
    /// <summary>Input tokens consumed (system + user prompt).</summary>
    public int PromptTokens { get; set; }

    /// <summary>Output tokens generated by the model.</summary>
    public int CompletionTokens { get; set; }

    /// <summary>Total tokens billed for the call.</summary>
    public int TotalTokens { get; set; }
}
